.ds-listing{display:flex;flex-direction:column;width:440px;height:260px;font:14px system-ui;color:#232a36;background:#fff;border-radius:0.5rem;overflow:hidden;box-shadow:0 1px 3px rgba(21, 26, 35, 0.1), 0 5px 12px rgba(21, 26, 35, 0.05)}.ds-table-scroll{flex:1;min-height:0;overflow:auto;scrollbar-gutter:stable;scrollbar-color:#8c959f #f0f2f5}.ds-listing table{border-collapse:separate;border-spacing:0;width:100%}.ds-listing th,.ds-listing td{padding:10px 12px;text-align:left;border-bottom:1px solid #d4dbe3}.ds-listing th{background:#f0f2f5;color:#5d6675;font-size:12.5px}.ds-listing a{color:#151a23;text-decoration:underline;text-underline-offset:.2em}.ds-listing a:hover{color:#2250c4}.ds-listing footer{flex-shrink:0;padding:10px 12px;border-top:1px solid #d4dbe3}.ds-listing small{font-size:13px;color:#5d6675}.ds-table-page-size label{display:flex;align-items:center;gap:8px}.ds-table-page-size select{min-height:32px;width:68px;background:#fff;color:#232a36;border:1px solid #8c959f;border-radius:0.375rem}.ds-table-pagination{display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 0.75rem 1rem;}.ds-table-page-size{margin: 0; font-size: 0.8125rem;}.ds-table-frame{position: relative; display: flex; flex-direction: column; min-width: 0; min-height: 0;}.ds-table-frame > .ds-table-scroll{flex: 1 1 auto; min-height: 0;}.ds-table-frame::before,
.ds-table-frame::after{content: ''; position: absolute; top: var(--app-table-header-height, 0px); right: 0; bottom: 0; left: 0; z-index: 3; pointer-events: none;}.ds-table-frame::after{box-shadow: var(--app-scroll-top, 0 0 transparent), var(--app-scroll-bottom, 0 0 transparent), var(--app-scroll-left, 0 0 transparent), var(--app-scroll-right, 0 0 transparent);}.ds-table-frame.has-more-above{--app-scroll-top: inset 0 8px 8px -8px rgba(21, 26, 35, 0.32);}.ds-table-frame.has-more-below{--app-scroll-bottom: inset 0 -8px 8px -8px rgba(21, 26, 35, 0.32);}.ds-table-frame.has-more-left{--app-scroll-left: inset 8px 0 8px -8px rgba(21, 26, 35, 0.32);}.ds-table-frame.has-more-right{--app-scroll-right: inset -8px 0 8px -8px rgba(21, 26, 35, 0.32);}.ds-table-frame > .ds-table-scroll:focus-visible{outline: none;}.ds-table-frame:has(> .ds-table-scroll:focus-visible)::before{z-index: 4; border: 2px solid #2250c4;}.ds-listing table > thead{position: sticky; top: 0; z-index: 6; background-color: #f0f2f5;}.ds-table-frame{flex:1 1 0;--app-table-header-height:40px}.ds-table-scroll{overscroll-behavior:none}
.ds-listing table tbody tr:has(a.ds-row-link) { position: relative; } a.ds-row-link::after { content: ''; position: absolute; inset: 0; z-index: 1; cursor: pointer; } a.ds-row-link:focus-visible { outline: none; } a.ds-row-link:focus-visible::after { outline: 2px solid #2250c4; outline-offset: -2px; } .ds-listing table tr:has(a.ds-row-link) :is(a, button):not(.ds-row-link), .ds-listing table tbody .dropdown { position: relative; z-index: 2; } .ds-listing table tbody .dropdown:has(.dropdown-menu.show) { z-index: 5; }

.ds-confirm-open {
    overflow: hidden;
}

.ds-confirm-dialog {
    position: fixed;
    inset: 0;
    width: min(30rem, calc(100% - 2rem));
    max-height: calc(100dvh - 2rem);
    margin: auto;
    padding: 0;
    overflow: hidden;
    color: #232a36;
    background: var(--bs-body-bg);
    border: 0;
    border-radius: 0.5rem;
    box-shadow: 0 0.5rem 1.5rem rgba(21, 26, 35, 0.12), 0 0.125rem 0.375rem rgba(21, 26, 35, 0.06);
}

.ds-confirm-dialog[open] {
    display: flex;
    flex-direction: column;
    animation: app-confirm-in 140ms cubic-bezier(0.16, 1, 0.3, 1);
}

.ds-confirm-dialog::backdrop {
    background: rgba(21, 26, 35, 0.35);
}

.ds-confirm-body {
    min-height: 0;
    padding: 1.5rem;
    overflow: auto;
}

.ds-confirm-heading {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding-right: 1.5rem;
    margin-bottom: 1.25rem;
}

.ds-confirm-heading h2 {
    margin: 0;
    font-size: 1.25rem;
    font-weight: 600;
    line-height: 1.3;
}

.ds-confirm-icon {
    display: inline-grid;
    flex-shrink: 0;
    place-items: center;
    width: 2rem;
    height: 2rem;
    color: #8e1f2a;
    background: #fbe8ea;
    border-radius: 0.25rem;
}

.ds-confirm-dialog--primary .ds-confirm-icon {
    color: #1a3e9a;
    background: #eaf0fd;
}

.ds-confirm-record {
    margin: 0 0 0.5rem;
    overflow-wrap: anywhere;
    font-weight: 600;
}

.ds-confirm-message {
    margin: 0;
    color: #5d6675;
}

.ds-confirm-close {
    position: absolute;
    top: 0.75rem;
    right: 0.75rem;
    padding: 0.625rem;
}

.ds-confirm-actions {
    display: flex;
    flex-shrink: 0;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 0.625rem;
    margin: 0;
    padding: 1rem 1.5rem;
    border-top: 1px solid #d4dbe3;
}

@keyframes app-confirm-in {
    from { opacity: 0; transform: translateY(0.25rem); }
    to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
    .ds-confirm-dialog[open] {
        animation: none;
    }
}


.ds-confirm{position:relative;inset:auto;width:440px;max-width:100%;max-height:none;margin:0;background:#fff;font:14px/1.5 system-ui;animation:none}.ds-confirm .btn{font:600 14px system-ui;min-height:38px;padding:8px 14px;border:1px solid #8c959f;border-radius:0.375rem;background:#fff;color:#151a23;box-shadow:0 1px 2px rgba(21, 26, 35, 0.08)}.ds-confirm .btn-danger{background:#c62d3a;border-color:#c62d3a;color:#fff}.ds-confirm .btn-close{width:20px;height:20px;border:0;background:transparent}.ds-confirm .btn-close::before{content:"×";font-size:24px;line-height:20px;color:#5d6675}
